class Solution {
public:
    long long shiftDistance(string s, string t, vector<int>& nextCost, vector<int>& previousCost) {
        vector<vector<long long>> cost(26, vector<long long>(26, 0));
        for (int u = 0; u < 26; ++u) {
            for (int v = 0; v < 26; ++v) {
                if (u == v) continue;
                long long fwd = 0;
                int curr = u;
                while (curr != v) {
                    fwd += nextCost[curr];
                    curr = (curr + 1) % 26;
                }
                long long bwd = 0;
                curr = u;
                while (curr != v) {
                    bwd += previousCost[curr];
                    curr = (curr - 1 + 26) % 26;
                }
                cost[u][v] = min(fwd, bwd);
            }
        }
        long long ans = 0;
        for (size_t i = 0; i < s.length(); ++i) {
            ans += cost[s[i] - 'a'][t[i] - 'a'];
        }
        return ans;
    }
};

