var shiftDistance = function(s, t, nextCost, previousCost) {
    const cost = Array.from({ length: 26 }, () => Array(26).fill(0));
    for (let u = 0; u < 26; u++) {
        for (let v = 0; v < 26; v++) {
            if (u === v) continue;
            let fwd = 0;
            let curr = u;
            while (curr !== v) {
                fwd += nextCost[curr];
                curr = (curr + 1) % 26;
            }
            let bwd = 0;
            curr = u;
            while (curr !== v) {
                bwd += previousCost[curr];
                curr = (curr - 1 + 26) % 26;
            }
            cost[u][v] = Math.min(fwd, bwd);
        }
    }
    let ans = 0;
    for (let i = 0; i < s.length; i++) {
        ans += cost[s.charCodeAt(i) - 97][t.charCodeAt(i) - 97];
    }
    return ans;
};
